     "summary": "10月18日，由中铁十四局承建的宜昌至涪陵（宜涪）高铁湖北段首座“全隧浅埋”隧道郭家坡隧道贯通，为后续施工及项目全线通车奠定了坚实基础。宜涪高铁是国家“八纵八横”高铁网沿江通道的重要组成部分，建成通车后，将形成川渝地区与华中地区之间的高速铁路新通道，对促进沿线经济社会发展具有重要意义。（新华社）（文章来源：新华社）",
